        steel_hard: { kc: 2800, speedFactor: 0.65, feedFactor: 0.75, rampAngle: 2, helixAngle: 1 },
        steel_tool: { kc: 3200, speedFactor: 0.50, feedFactor: 0.65, rampAngle: 1.5, helixAngle: 0.75 },

        // ISO M - Stainless
