        // EXPOSED HOLDER GEOMETRY CALCULATOR
        // Calculates volume/surfaceArea from spindle face to tool (excludes taper)
        calculateExposedHolderGeometry: function(holder) {
            const TAPER_SPECS = {
                'CAT30': { taperLength: 47.625, flangeOD: 44.45 },
                'CAT40': { taperLength: 63.5, flangeOD: 63.5 },
                'CAT50': { taperLength: 88.9, flangeOD: 100 },
                'BT30': { taperLength: 47.625, flangeOD: 44.45 },
                'BT40': { taperLength: 63.5, flangeOD: 63.5 },
                'BT50': { taperLength: 88.9, flangeOD: 100 },
                'HSK40': { taperLength: 30, flangeOD: 53 },
                'HSK63': { taperLength: 40, flangeOD: 85 },
                'HSK63A': { taperLength: 40, flangeOD: 85 },
                'HSK100': { taperLength: 60, flangeOD: 132 },
                'HSK100A': { taperLength: 60, flangeOD: 132 },
                'R8': { taperLength: 88.9, flangeOD: 31.75 }
            };
            const taper = holder.taper || 'CAT40';
            const spec = TAPER_SPECS[taper] || TAPER_SPECS['CAT40'];
            let projectionMM = holder.projection || 70;
            if (holder.projection < 10) projectionMM = holder.projection * 25.4;
            let bodyDiaMM;
            switch(holder.type) {
                case 'shrink_fit': bodyDiaMM = spec.flangeOD * 0.55; break;
                case 'hydraulic_chuck': case 'hydraulic': bodyDiaMM = spec.flangeOD * 0.75; break;
                case 'collet_chuck': case 'er_collet': bodyDiaMM = spec.flangeOD * 0.85; break;
                case 'milling_chuck': case 'power_chuck': bodyDiaMM = spec.flangeOD * 0.8; break;
                case 'shell_mill_arbor': case 'face_mill_arbor': bodyDiaMM = spec.flangeOD * 0.6; break;
                default: bodyDiaMM = spec.flangeOD * 0.7;
            }
            const flangeThickness = 15;
            const flangeVolume = Math.PI * Math.pow(spec.flangeOD/2, 2) * flangeThickness;
            const bodyVolume = Math.PI * Math.pow(bodyDiaMM/2, 2) * (projectionMM - flangeThickness);
            const exposedVolume = Math.round(flangeVolume + bodyVolume);
            const flangeSurface = 2 * Math.PI * (spec.flangeOD/2) * flangeThickness + Math.PI * Math.pow(spec.flangeOD/2, 2);
            const bodySurface = 2 * Math.PI * (bodyDiaMM/2) * (projectionMM - flangeThickness);
            const exposedSurface = Math.round(flangeSurface + bodySurface);
            return {
                exposedVolume: exposedVolume,
                exposedSurfaceArea: exposedSurface,
                flangeOD: spec.flangeOD,
                bodyDiameter: bodyDiaMM,
                projectionLength: projectionMM,
                taperExcluded: true,
                units: 'mm3/mm2',
                note: 'Geometry from spindle face contact to holder face only'
            };
        },
