    // DRILL SPEED CALCULATOR HELPER FUNCTIONS

    function getDrillSpeedRecommendation(materialId, drillMaterial, diameter) {
        const matData = DRILL_DATABASE.speedFeedRecommendations[materialId];
        if (!matData) return null;

        const drillData = matData[drillMaterial] || matData.hss;
        const sfm = drillData.sfm[1]; // Use recommended value
        const ipr = drillData.ipr[1];

        // Calculate RPM: RPM = (SFM × 3.82) / Diameter
        const rpm = Math.round((sfm * 3.82) / diameter);

        // Calculate Feed Rate (IPM): IPM = RPM × IPR
        const feedIpm = Math.round(rpm * ipr * 1000) / 1000;

        return {
            sfm: sfm,
            rpm: rpm,
            ipr: ipr,
            feedIpm: feedIpm,
            coolant: matData.coolant,
            notes: matData.notes
        };
    }
    function getDrillCoatingRecommendation(workMaterial, drillMaterial) {
        // Basic recommendation logic
        const recommendations = [];

        if (workMaterial.includes('aluminum') || workMaterial.includes('copper')) {
            recommendations.push('zrn', 'dlc', 'uncoated');
        } else if (workMaterial.includes('stainless') || workMaterial.includes('titanium') || workMaterial.includes('inconel')) {
            recommendations.push('altin', 'tialn', 'alcrn');
        } else if (workMaterial.includes('hardened')) {
            recommendations.push('altin', 'naco', 'tialsin');
        } else if (workMaterial.includes('cast_iron')) {
            recommendations.push('ticn', 'tialn', 'tin');
        } else {
            recommendations.push('tin', 'tialn', 'black_oxide');
        }
        return recommendations.map(id => DRILL_DATABASE.coatings[id]).filter(Boolean);
    }
