    // Generate pricing estimates from various suppliers
    function generateDrillPricing(drill, basePrice) {
        const partNo = encodeURIComponent(drill.partNo);
        const brandKey = drill.brand?.toLowerCase() || '';

        // Price variance based on supplier type
        const suppliers = [
            {
                name: 'MSC Industrial',
                icon: '🏭',
                priceMultiplier: 1.0,
                note: 'Industrial supplier • Usually in stock',
                shipping: 'Free over $99',
                url: `https://www.mscdirect.com/browse/tnpla?searchterm=${partNo}`
            },
            {
                name: 'Grainger',
                icon: '🔧',
                priceMultiplier: 1.08,
                note: 'Same-day pickup available',
                shipping: 'Free pickup',
                url: `https://www.grainger.com/search?searchQuery=${partNo}`
            },
            {
                name: 'McMaster-Carr',
                icon: '📦',
                priceMultiplier: 1.05,
                note: 'Fast shipping • No account needed',
                shipping: 'Ships same day',
                url: `https://www.mcmaster.com/drills`
            },
            {
                name: 'Amazon Business',
                icon: '📱',
                priceMultiplier: 0.95,
                note: 'Prime shipping • Marketplace pricing',
                shipping: 'Prime 2-day',
                url: `https://www.amazon.com/s?k=${partNo}`
            },
            {
                name: 'Zoro',
                icon: '🛒',
                priceMultiplier: 0.92,
                note: 'Budget option • Free shipping',
                shipping: 'Free over $50',
                url: `https://www.zoro.com/search?q=${partNo}`
            },
            {
                name: 'eBay Industrial',
                icon: '🔨',
                priceMultiplier: 0.85,
                note: 'Auction/Buy Now • Check seller rating',
                shipping: 'Varies',
                url: `https://www.ebay.com/sch/i.html?_nkw=${partNo}`
            }
        ];

        // Add manufacturer-specific suppliers
        const mfgSuppliers = {
            guhring: { name: 'Guhring Direct', icon: '🏢', mult: 1.0, url: 'https://www.guhring.com' },
            osg: { name: 'OSG USA', icon: '🏢', mult: 1.0, url: 'https://www.osgtool.com' },
            kennametal: { name: 'Kennametal Direct', icon: '🏢', mult: 1.0, url: 'https://www.kennametal.com' },
            sandvik: { name: 'Sandvik Shop', icon: '🏢', mult: 1.0, url: 'https://shop.sandvik.coromant.com' },
            yg1: { name: 'YG-1 Shop', icon: '🏢', mult: 0.9, url: 'https://www.yg1usa.com' }
        };
        if (mfgSuppliers[brandKey]) {
            const mfg = mfgSuppliers[brandKey];
            suppliers.push({
                name: mfg.name,
                icon: mfg.icon,
                priceMultiplier: mfg.mult,
                note: 'Direct from manufacturer',
                shipping: 'Standard',
                url: mfg.url
            });
        }
        // Calculate prices with some variance
        return suppliers.map(s => ({
            ...s,
            price: Math.round(basePrice * s.priceMultiplier * (0.95 + Math.random() * 0.1) * 100) / 100
        }));
    }
