// HELPER FUNCTIONS FOR POST PROCESSOR CALCULATIONS

/**
 * Calculate chip thinning factor
 * @param {number} toolDia - Tool diameter
 * @param {number} radialEngagement - Radial depth of cut (ae)
 * @returns {number} Chip thinning factor
 */
function calculateChipThinningFactor(toolDia, radialEngagement) {
    const aeRatio = radialEngagement / toolDia;

    if (aeRatio >= 0.5) return 1.0;
    if (aeRatio <= 0) return 1.0;

    // CTF = D / (2 * sqrt(ae * (D - ae)))
    const ctf = toolDia / (2 * Math.sqrt(radialEngagement * (toolDia - radialEngagement)));

    return Math.min(ctf, POST_PROCESSOR_DATABASE.FEED_OPTIMIZATION.chipThinning.maxMultiplier);
}
/**
 * Calculate tool deflection
 * @param {number} force - Cutting force (lbs)
 * @param {number} stickout - Tool stickout (inches)
 * @param {number} diameter - Tool diameter (inches)
 * @param {string} material - Tool material ('carbide' or 'hss')
 * @returns {number} Deflection in inches
 */
function calculateToolDeflection(force, stickout, diameter, material = 'carbide') {
    const E = material === 'carbide' ? 84000000 : 30000000;  // psi
    const I = Math.PI * Math.pow(diameter, 4) / 64;  // Moment of inertia

    // δ = F * L³ / (3 * E * I)
    const deflection = (force * Math.pow(stickout, 3)) / (3 * E * I);

    return deflection;
}
/**
 * Calculate specific cutting force using Kienzle equation
 * @param {string} material - Material type
 * @param {number} chipThickness - Chip thickness (mm)
 * @returns {number} Specific cutting force (N/mm²)
 */
function calculateSpecificCuttingForce(material, chipThickness) {
    const data = POST_PROCESSOR_DATABASE.MACHINING_SCIENCE.specificCuttingForce[material];
    if (!data) return 2000;  // Default for unknown materials

    // Kc = Kc1.1 * h^(-mc)
    return data.Kc1_1 * Math.pow(chipThickness, -data.mc);
}
/**
 * Calculate theoretical surface finish (Ra)
 * @param {number} feedPerRev - Feed per revolution (inches)
 * @param {number} noseRadius - Tool nose radius (inches)
 * @returns {number} Ra in microinches
 */
function calculateSurfaceFinish(feedPerRev, noseRadius) {
    // Ra ≈ f² / (32 * r) (simplified formula)
    const raMm = Math.pow(feedPerRev * 25.4, 2) / (32 * noseRadius * 25.4);
    return raMm * 39.37;  // Convert to microinches
}
/**
 * Calculate arc feed correction factor
 * @param {number} arcRadius - Arc radius (inches)
 * @param {number} toolRadius - Tool radius (inches)
 * @param {boolean} convex - True for outside arc, false for inside
 * @returns {number} Feed correction factor (0.5 to 1.0)
 */
function calculateArcFeedCorrection(arcRadius, toolRadius, convex = true) {
    if (arcRadius <= toolRadius) return 0.5;  // Minimum

    const config = POST_PROCESSOR_DATABASE.FEED_OPTIMIZATION.iMachining.arcCorrection;

    if (convex) {
        // Outside arc - tool moves slower
        return Math.max(1 - (toolRadius / arcRadius) * config.factor, 1 - config.maxCorrection);
    } else {
        // Inside arc - could theoretically go faster, but usually maintain
        return 1.0;
    }
}
/**
 * Calculate dynamic depth feed adjustment
 * @param {number} programmedDOC - Programmed depth of cut
 * @param {number} actualDOC - Actual depth of cut
 * @returns {number} Feed multiplier
 */
function calculateDynamicDepthFeed(programmedDOC, actualDOC) {
    if (actualDOC >= programmedDOC) return 1.0;
    if (actualDOC <= 0) return 1.0;

    const config = POST_PROCESSOR_DATABASE.FEED_OPTIMIZATION.adaptiveDepth;
    const ratio = actualDOC / programmedDOC;

    // Feed increase = sqrt(programmedDOC / actualDOC)
    let multiplier = Math.sqrt(programmedDOC / actualDOC);

    return Math.min(multiplier, config.maxIncrease);
}
/**
 * Calculate optimal cutting speed using Taylor equation
 * @param {string} material - Material type
 * @param {number} desiredToolLife - Desired tool life in minutes
 * @returns {number} Optimal cutting speed (SFM)
 */
function calculateOptimalSpeed(material, desiredToolLife = 45) {
    const data = POST_PROCESSOR_DATABASE.MACHINING_SCIENCE.taylorConstants[material];
    if (!data) return 300;  // Default

    // V = C / T^n
    return data.C / Math.pow(desiredToolLife, data.n);
}
/**
 * Get post processor configuration for a machine
 * @param {string} machineId - Machine identifier
 * @returns {object} Post processor configuration
 */
function getPostConfig(machineId) {
    const machine = POST_PROCESSOR_DATABASE.MACHINES[machineId];
    if (!machine) return null;

    // Get controller configuration
    const controllerPath = machine.controller.split('.');
    let controller = POST_PROCESSOR_DATABASE.CONTROLLERS;
    for (const part of controllerPath) {
        controller = controller[part];
    }
    // Merge inherited configurations
    let config = { ...controller };
    if (controller.inherits) {
        const inheritPath = controller.inherits.split('.');
        let parent = POST_PROCESSOR_DATABASE.CONTROLLERS;
        for (const part of inheritPath) {
            parent = parent[part];
        }
        config = { ...parent, ...config };
    }
    return {
        machine: machine,
        controller: config,
        postConfig: machine.postConfig
    };
}
// Export for use in PRISM
if (typeof module !== 'undefined' && module.exports) {
    module.exports = {
        POST_PROCESSOR_DATABASE,
        calculateChipThinningFactor,
        calculateToolDeflection,
        calculateSpecificCuttingForce,
        calculateSurfaceFinish,
        calculateArcFeedCorrection,
        calculateDynamicDepthFeed,
        calculateOptimalSpeed,
        getPostConfig
    };
}
